#pragma once
#include <cstdint>
#include <vector>
namespace Cortex
{
// Derived contents are regenerated by each query; only capacity persists.
struct WaterScratch
{
    std::vector<char> visited;
    std::vector<int> frontier, land, swim, target;
};
struct WheatScratch
{
    std::vector<int> fieldTiles, depth, queue, stack;
    std::vector<unsigned char> seen, currentBit;
    std::vector<int> current;
};
struct QueryScratch
{
    std::vector<unsigned char> proximity;
    WaterScratch water;
    WheatScratch wheat;
    std::uint64_t retainedVectorBytes() const
    {
        std::uint64_t bytes=proximity.capacity()+water.visited.capacity()
            +wheat.seen.capacity()+wheat.currentBit.capacity();
        for(const auto* v:{&water.frontier,&water.land,&water.swim,&water.target,
                &wheat.fieldTiles,&wheat.depth,&wheat.queue,&wheat.stack,&wheat.current})
            bytes+=v->capacity()*sizeof(int);
        return bytes;
    }
};
}
